            CREATE TABLE IF NOT EXISTS `translations` (
                `translation` VARCHAR(255) PRIMARY KEY,
                `title` VARCHAR(255),
                `license` TEXT
            );
            

            VALUES ('RusSynodal', '# RusSynodal: Синодального Перевода Библии', 'Public Domain')
            ON DUPLICATE KEY UPDATE
                `title` = VALUES(`title`),
                `license` = VALUES(`license`);
            

            CREATE TABLE `RusSynodal_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `RusSynodal_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `book_id` INT,
                `chapter` INT,
                `verse` INT,
                `text` TEXT,
